import csv
from collections import defaultdict
rows=list(csv.DictReader(open(CATALOG_CSV)))
ids={r['timeseries_id']:r['point_uri'].split('#')[1] for r in rows}
series=defaultdict(dict)
for t in csv.DictReader(open(VALUES_CSV)):
    series[t['timeseries_id']][t['timestamp']]=float(t['value'])

def zone_mean(name, period):
    for k,v in series.items():
        if ids[k]==name+'.Zone_Air_Temperature_Sensor':
            ts=[(t,val) for t,val in v.items() if period(t)]
            ts.sort()
            import statistics
            return statistics.mean(x[1] for x in ts), statistics.stdev(x[1] for x in ts)
    return None

pre = lambda t: t < '2018-07-01'
post = lambda t: t >= '2018-07-01'
zones = sorted(set(n.split('.')[0] for n in ids.values() if n.endswith('.Zone_Air_Temperature_Sensor')))
for z in zones:
    m1,m2 = zone_mean(z,pre), zone_mean(z,post)
    print(z, round(m1[0],2), round(m1[1],2), round(m2[0],2), round(m2[1],2), 'delta', round(m2[0]-m1[0],2))

